import * as U from '../ui.js';
U.mount(()=>U.heading('One small step at a time','Welcome to your campus life.','A little setup today. A much easier week tomorrow.','<a class="btn" href="index.html">Skip to Today →</a>')+`<div class="intro-banner"><div><h2>You don’t have to figure it all out at once.</h2><p>Start with your courses, add your classes, then make a little room for what matters.</p></div>${U.icon('study')}</div><div class="dashboard-grid"><div class="stack">${U.section('Your getting-started checklist',`<div class="setup-step"><span class="step-number">1</span><div class="grow"><h3>Make yourself at home</h3><p>Set your name, timezone, and preferred currency.</p></div>${U.button('Edit profile','users',U.db.users[0].id)}</div><div class="setup-step"><span class="step-number">2</span><div class="grow"><h3>Add your courses</h3><p>${U.db.courses.length} courses saved in your workspace.</p></div>${U.button('Add course','courses')}</div><div class="setup-step"><span class="step-number">3</span><div class="grow"><h3>Map out your week</h3><p>Add recurring lecture times and classroom locations.</p></div>${U.button('Add schedule','schedules')}</div><div class="setup-step"><span class="step-number">4</span><div class="grow"><h3>Give your money a plan</h3><p>Choose a monthly spending limit you’re comfortable with.</p></div>${U.button('Set budget','monthly_budgets',U.budgetSummary().budget?.id||'')}</div><div style="margin-top:25px"><a class="btn primary" href="index.html">I’m ready. Show my day ${U.icon('arrow')}</a></div>`)}</div><div class="stack">${U.section('Take a look around',`<p class="small muted" style="line-height:1.9">Your courses, timetable, tasks, and budget belong to your signed-in account. Add your own information to make this space useful for your day.</p><div class="note" style="margin-top:18px">${U.icon('info')}<span>Your changes are saved to your account on this Campus installation.</span></div>`)}</div></div>`);
